function objectsPage(){const o=obj();return header('对象与数据','从业务对象出发，统一管理属性、数据来源和应用引用。',btn('添加业务对象','add-object','primary','plus'))+journey(0)+`<div class="object-layout"><section class="panel object-list"><div class="list-top"><div class="between list-title"><h3>业务对象</h3><span class="muted tiny">${objects.filter(visible).length} 个</span></div><div class="search">${icon('search')}<input aria-label="搜索对象" id="object-search" placeholder="搜索对象名称或标识" value="${esc(state.query)}" data-input="object-search"></div></div><div class="object-items" id="object-items">${objectItems()}</div><div class="directory-note">公共对象可被业务域引用<br>新建对象与接入数据在此完成</div></section><section class="panel object-detail"><div class="object-heading"><div class="between"><div><div class="row"><h2>${esc(o.name)}</h2>${pill(o.status,o.status==='已发布'?'green':'amber')}${pill(o.domain==='COMMON'?'公共域':'项目管理域')}</div><p class="muted tiny" style="margin-top:9px;line-height:1.7">${esc(o.desc)}</p></div>${btn('测试对应关系','test-object','','play')}</div><div class="object-meta"><code>${esc(o.id)}</code><span>配置 ${o.version}</span><span>${o.count.toLocaleString()} 条示例记录</span><span>唯一编号已配置</span></div></div><div class="tabs" role="tablist">${[['props','属性与来源',o.props.length],['relations','关联关系',relations.filter(r=>r.from===o.id||r.to===o.id).length],['preview','数据预览',''],['refs','应用引用',''],['versions','版本记录','']].map(([id,t,c])=>`<button role="tab" aria-selected="${state.tab===id}" class="tab ${state.tab===id?'active':''}" data-action="object-tab" data-tab="${id}">${t}<span>${c}</span></button>`).join('')}</div>${objectTab(o)}</section></div><p class="session-note">原型使用示例对象、表结构和业务数据。修改仅在当前页面会话保留，刷新可恢复初始状态。</p>`}
function visible(o){return state.domain==='ALL'||o.domain==='COMMON'||o.domain===state.domain}
function objectItems(){return objects.filter(o=>visible(o)&&(`${o.name} ${o.id}`.toLowerCase().includes(state.query.toLowerCase()))).map(o=>`<button class="object-item ${o.id===state.object?'active':''}" data-action="select-object" data-id="${o.id}"><span class="obj-icon">${icon('cube')}</span><span class="fill"><b>${esc(o.name)}</b><span class="sub"><span class="dot ${o.status==='已发布'?'':'draft'}"></span>${o.status}<span>·</span>${o.props.length} 个属性</span><small>${esc(o.id)}</small></span></button>`).join('')||'<div class="empty">未找到对象<br>试试其他名称，或添加新对象</div>'}
function objectTab(o){if(state.tab==='props')return `${sourceSummary(o)}<div class="table-toolbar"><div class="row"><h3>业务属性</h3><span class="muted tiny">${o.props.length} 项 · 数据来源完整</span></div>${btn('添加属性','add-prop','sm','plus')}</div><div class="table-wrap"><table><thead><tr><th>属性名称 / 标识</th><th>数据类型</th><th>约束</th><th>权威来源</th><th>对应关系状态</th><th>操作</th></tr></thead><tbody>${o.props.map((p,i)=>`<tr><td class="field-name">${esc(p.name)}<small>${esc(p.id)}</small></td><td><span class="field-type">${p.type}</span></td><td><div class="cell-badges">${p.key?'<span class="mini-tag">唯一编号</span>':''}${p.display?'<span class="mini-tag gray">展示名</span>':''}${p.required&&!p.key?'<span class="mini-tag gray">必填</span>':''}${!p.key&&!p.display&&!p.required?'<span class="muted tiny">—</span>':''}</div></td><td><div class="source-label"><i>${p.source.includes('数据库')?'DB':p.source.includes('接口')?'API':'VAL'}</i>${esc(p.source)}</div><small class="muted" style="font-size:10px">${esc(p.freshness||(p.source.includes('接口')?(o.strategy?.dynamic||'按需实时查询'):p.source.includes('数据库')?(o.strategy?.stable||'每 30 分钟同步'):'运行时获取'))}</small></td><td><span class="pill green"><span class="dot"></span>已对应关系</span></td><td><button class="link" data-action="edit-prop" data-index="${i}">配置</button></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>对象主键用于识别记录，展示名用于页面阅读</span><span>技术字段已隐藏 · 仅展示业务属性</span></div>`;
if(state.tab==='relations')return `<div class="table-toolbar"><h3>与 ${esc(o.name)} 相关的业务关系</h3>${btn('配置关系','to-relations','sm','link')}</div>${relationTable(relations.filter(r=>r.from===o.id||r.to===o.id))}<div class="panel-body">${inf('先定义业务关系，再配置字段匹配、关联表或接口。Mapping 通过发布项 ID 引用具体发布行。')}</div>`;
if(state.tab==='preview')return `<div class="panel-body">${inf('以下为转换后的单条示例记录，不代表线上数据。API 状态在使用时实时获取。')}<div class="section-gap table-wrap"><table><thead><tr><th>业务属性</th><th>转换后的值</th><th>原始来源路径</th></tr></thead><tbody>${o.props.map(p=>`<tr><td>${p.name}</td><td>${esc(p.value)}</td><td><code>${esc(p.path)}</code></td></tr>`).join('')}</tbody></table></div></div>`;
if(state.tab==='refs')return referenceView(o);
return `<div class="panel-body"><div class="timeline"><div class="timeline-item"><b>${o.version} · ${o.status}</b><p>当前工作区 · 2026-10-27<br>完善数据来源与属性业务含义，关联产品发布单应用。</p></div><div class="timeline-item"><b>v1.0 · 初始建模</b><p>2026-10-22 · 平台管理员<br>建立稳定业务主键，完成基础字段对应。</p></div></div>${btn('查看配置发布','to-release','','upload')}</div>`;}
function relationTable(list){return `<div class="table-wrap"><table class="config-table"><thead><tr><th>业务关系</th><th>源对象 → 目标对象</th><th>基数</th><th>关联方式</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(r=>`<tr><td class="field-name">${esc(r.name)}</td><td>${esc(name(r.from))}<span class="muted"> → </span>${esc(name(r.to))}</td><td>${r.card}</td><td>${r.method}</td><td>${pill('已配置','green')}</td><td><button class="link" data-action="edit-relation" data-index="${relations.indexOf(r)}">配置</button> <button class="link danger-text" data-action="delete-relation" data-index="${relations.indexOf(r)}">删除</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">当前没有相关关系，可点击“添加关系”建立关联。</td></tr>'}</tbody></table></div>`}
function relationsPage(){return header('对象关系','用业务语言定义关联，再选择数据如何匹配。',btn('添加关系','add-relation','primary','plus'))+journey(1)+`<section class="panel"><div class="filterbar"><div class="row fill">${icon('link')}<h3>业务关系</h3><span class="muted tiny">${relations.length} 条</span></div>${pill('模型层 · 关系定义','blue')}</div>${relationTable(relations)}</section><div class="section-gap">${inf('整机—软件 Mapping 是关系对象：引用发布清单行 RI-001，而非仅按 MAT-20260081 这样的物料编码匹配。')}</div>`}
function bindingsPage(){const list=bindings[state.block];return header('应用字段绑定','将业务属性放到正确的表单区块、行和 API 字段。',btn('测试填单','test-binding','','play')+btn('添加字段绑定','add-binding','primary','plus'),'APPLICATION CONFIGURATION')+journey(2)+`<section class="panel"><div class="filterbar"><span class="tiny muted">应用</span><select class="select" aria-label="应用"><option>产品发布单</option></select><span class="tiny muted">场景</span><select class="select" data-change="binding-scene" aria-label="业务场景">${options(['普通产品发布','产品范围发布'],state.bindingScene||'普通产品发布')}</select><span class="tiny muted">表单版本</span>${pill('V3','blue')}<span class="fill"></span>${pill('配置草稿','amber')}</div><div class="binding-layout"><aside class="binding-tree"><div class="tree-label">表单区块</div>${Object.entries(blockNames).map(([id,n])=>`<button class="tree-item ${state.block===id?'active':''}" data-action="binding-block" data-block="${id}">${icon(id==='mapping'?'link':id==='main'?'file':'grid')}<span>${n}</span><small>${bindings[id].length}</small></button>`).join('')}</aside><div><div class="table-toolbar"><div><h3>${blockNames[state.block]}</h3><p class="muted tiny" style="margin-top:7px">${state.block==='main'?'单据级上下文':state.block==='mapping'?'引用当前主单内的发布项及模块子单':'逐行绑定 · 不同行使用各自的数据'}</p></div>${pill(`${list.length} 项已绑定`,'green')}</div><div class="table-wrap"><table><thead><tr><th>目标字段 / 路径</th><th>业务属性</th><th>写入方式</th><th>已有内容怎么处理</th><th>操作</th></tr></thead><tbody>${list.map((b,i)=>`<tr><td class="field-name">${esc(b.label)}<code class="field-path">${esc(b.target)}</code></td><td><span style="font-size:11px">${esc(semanticPath(b.ontology))}</span><span class="field-path">${esc(b.method)}</span></td><td>${pill(b.direction,b.direction==='只读'?'':'blue')}</td><td><span class="tiny muted">${esc(b.policy)}</span></td><td><button class="link" data-action="edit-binding" data-index="${i}">配置</button></td></tr>`).join('')}</tbody></table></div><div class="panel-body">${inf(state.block==='mapping'?'保存引用 ID：RI-001 / MO-001。物料编码只用于展示，同物料的不同发布行不会被混为一行。':'用户手工修改的字段默认保留；新的智能建议展示差异，由用户确认后写入。')}<div class="mini-flow section-gap"><span>用户表达 / 权威数据</span>${icon('arrow')}<b>业务属性</b>${icon('arrow')}<b>表单与 API 字段</b>${icon('arrow')}<span>业务后端保存</span></div></div></div></div></section><p class="session-note">业务对象平台配置前两层对应关系；API 到数据库的持久化由发布单系统后端负责。</p>`}
function semanticPath(s){const [id,p]=s.split('.');return `${name(id)}.${obj(id)?.props.find(x=>x.id===p)?.name||p||''}`}
const actions=[['读取发布单','读取主单、子单和 Mapping，形成当前操作上下文。','GET /release-orders/{id}','eye'],['生成填单建议','按字段绑定生成建议，保留用户已经修改的内容。','POST /release-orders/suggestions','bind'],['保存发布草稿','用户确认后，由发布单业务接口保存当前内容。','POST /release-orders/drafts','file'],['执行发布预校验','获取所需事实，返回结论、证据与问题定位。','POST /release-orders/validate','shield'],['提交发布单','确认单据版本，后端执行终检并进入现有审批流程。','POST /release-orders/{id}/submit','upload']];
function actionsPage(){return header('业务动作','定义业务对象应用如何读取、建议、校验和提交业务单据。',btn('体验智能提单','smart-draft','primary','play'),'APPLICATION ACTIONS')+`<div class="cards">${actions.map((a,i)=>`<section class="panel action-card"><div class="between"><span class="icon-tile">${icon(a[3])}</span>${pill(i===4?'终检后执行':'已配置',i===4?'amber':'green')}</div><h3>${a[0]}</h3><p>${a[1]}</p><code class="mono">${a[2]}</code><footer><span class="muted tiny">产品发布单 · V3</span><button class="link" data-action="action-detail" data-index="${i}">查看配置</button></footer></section>`).join('')}</div><div class="section-gap">${inf('生成建议、保存草稿和提交是三个独立动作。提交由业务后端执行权限、版本、幂等及最终规则检查。原型不调用真实接口。')}</div>`}
function rulesPage(){return header('校验规则','把发布要求配置为可测试、可解释、可定位的问题。',btn('调试发布单','validate','primary','play'),'RELEASE VALIDATION')+`<section class="panel"><div class="rule-summary"><div class="metric"><b>4</b>已启用规则</div><div class="metric"><b>${state.checked?validationResults().filter(x=>x.status!=='通过').length:'—'}</b>最近调试待处理项</div><div class="metric"><b>1</b>待确认业务口径</div><div class="metric"><b>V3</b>目标表单版本</div></div><div class="filterbar"><div class="row fill"><h3>产品发布单规则集</h3>${pill('确定性校验','blue')}</div><span class="muted tiny">触发于预校验、最终提交</span></div><div class="table-wrap"><table><thead><tr><th>规则名称 / 标识</th><th>适用对象</th><th>级别</th><th>事实来源</th><th>版本 / 状态</th><th>操作</th></tr></thead><tbody>${rules.map((r,i)=>`<tr><td class="field-name">${r.name}<small>${r.id}</small></td><td>${r.obj}</td><td>${pill(r.level,r.level==='阻断'?'red':'amber')}</td><td>${r.source}</td><td>${pill(r.version,i===4?'':'green')}</td><td><button class="link" data-action="edit-rule" data-index="${i}">${i===4?'查看待确认项':'配置 / 测试'}</button></td></tr>`).join('')}</tbody></table></div></section><div class="section-gap">${inf('DI 汇总口径和阈值未确定，该规则保持未启用。接口超时会返回“未能取得数据”，不会显示为业务不满足或通过。','amber')}</div>`}
function graphPage(){const nodes=[['ReleaseOrder',329,185],['ReleaseItem',80,60],['Material',80,310],['ModuleOrder',570,60],['Software',570,310],['Mapping',330,355],['Certification',330,25]];return header('图谱浏览','查看模型关系，并从节点进入对象定义或示例记录。',btn('查看示例记录','graph-instance','','eye'),'ONTOLOGY EXPLORER')+`<section class="panel"><div class="filterbar"><div class="row fill">${pill('模型视图','blue')}<span class="muted tiny">产品发布单 · 核心关系</span></div><button class="link" data-action="to-relations">管理关系</button></div><div class="graph-wrap"><div class="graph-canvas"><svg class="graph-lines" viewBox="0 0 800 470"><path d="M329 212 222 100M150 133v177M471 212 570 100M641 133v177M400 257v98M330 381 222 350M471 381 570 350M400 185V97"/><text x="225" y="142">包含发布项</text><text x="160" y="228">发布目标</text><text x="498" y="140">包含子单</text><text x="650" y="230">发布软件</text><text x="410" y="313">定义</text><text x="242" y="355">引用</text><text x="502" y="355">关联</text><text x="410" y="145">认证上下文</text></svg>${nodes.map(([id,x,y])=>`<button class="graph-node ${id==='ReleaseOrder'?'center':''}" style="left:${x}px;top:${y}px" data-action="graph-node" data-id="${id}"><div class="row">${icon(id==='Mapping'?'link':'cube')}<b>${name(id)}</b></div><small>${id}</small></button>`).join('')}</div></div><div class="table-foot"><span>示意图仅展示核心关系，认证上下文为派生路径</span><span>点击节点查看属性与来源</span></div></section>`}
function flowsPage(){return header('流程模板','管理智能提单与校验的执行步骤，衔接现有发布审批。','','APPLICATION ORCHESTRATION')+`<section class="panel"><div class="panel-head between"><div class="row"><h3>产品发布 · 智能提单</h3>${pill('示意模板','blue')}</div>${btn('体验执行','smart-draft','sm','play')}</div><div class="panel-body"><div class="flow-blocks">${[['需求解析','提取项目、整机及软件'],['获取事实','按业务对象来源配置取数'],['生成建议','按区块、行绑定字段'],['用户确认','保留修改及稳定引用'],['执行校验','确定性规则判断']].map(([t,s],i)=>`${i?icon('arrow'):''}<div class="flow-block"><h3>${t}</h3><small>${s}</small></div>`).join('')}</div>${inf('这是应用执行模板说明视图。产品发布单的审批节点仍由现有业务系统承接，本原型不提供完整审批流程设计器。')}</div></section>`}
function releasePage(){const total=objects.reduce((n,o)=>n+o.props.length,0);return header('配置发布','把模型、对应关系、关系、应用绑定和规则作为关联版本一起检查。',btn('检查配置','check-release','','shield')+btn(state.released?'已发布模拟版本':'发布配置包','publish','primary','upload',state.released?'disabled':''),'CONFIGURATION RELEASE')+journey(3)+`<div class="two-cols"><section class="panel"><div class="panel-head between"><h3>产品发布应用配置包</h3>${pill(state.released?'已发布':state.dirty?'有变更':'待发布',state.released?'green':'amber')}</div><div class="panel-body"><div class="row"><h2>release-app-v${state.version}.0</h2><span class="muted tiny">当前工作区</span></div>${[[`${objects.length} 个业务对象`,`${total} 个业务属性，业务主键与展示名分开配置`],[`${relations.length} 条对象关系`,'整机发布项、模块子单和 Mapping 引用'],[`${Object.values(bindings).flat().length} 项应用字段绑定`,'产品发布单 V3 · 四个表单区块'],['4 条启用规则 + 1 条未启用草稿','DI 口径未确认，未包含在启用规则集中']].map(([t,d])=>`<div class="release-line"><div class="release-check">${icon('check')}</div><div><h4>${t}</h4><p>${d}</p></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>变更与发布约束</h3></div><div class="panel-body"><div class="version-diff">+ 统一对象与数据接入入口<br>+ 数据库 / API 属性来源配置<br>+ 发布单 V3 表单与请求字段绑定<br>+ 保留发布项行 ID 的 Mapping 规则</div><ul class="checklist"><li>${icon('check')}每个对象具备记录的唯一编号</li><li>${icon('check')}字段绑定指向存在的业务属性</li><li>${icon('check')}必需对应关系和关系配置完整</li><li>${icon('check')}DI 草稿规则不参与本次启用</li></ul>${inf('点击发布仅生成模拟配置版本并写入本页运行记录，不修改任何公司系统。')}<div class="section-gap">${btn('查看运行记录','to-runs','','clock')}</div></div></section></div>`}
function runsPage(){return header('运行记录','区分同步、实时取数、规则校验和业务动作，定位每次执行。',btn('导出会话记录','export-logs','','download'),'EXECUTION HISTORY')+`<section class="panel"><div class="filterbar"><h3 class="fill">当前会话</h3><span class="muted tiny">${state.logs.length} 条记录 · 刷新后重置</span></div>${state.logs.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>执行内容</th><th>结果</th><th>详情</th></tr></thead><tbody>${state.logs.map((l,i)=>`<tr><td><code>${l.time}</code></td><td>${l.type}</td><td>${esc(l.title)}</td><td>${pill(l.result,l.result==='成功'||l.result==='通过'?'green':l.result==='阻断'?'red':'amber')}</td><td><button class="link" data-action="log-detail" data-index="${i}">查看证据</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('clock')}<b>当前会话还没有执行记录</b>测试一次对应关系或调试发布单，结果会出现在这里。<div style="margin-top:18px">${btn('调试发布单','validate','','play')}</div></div>`}</section>`}
function knowledgePage(){return header('知识关联','把说明文档关联到业务对象，作为问答的检索依据。','','KNOWLEDGE CONTEXT')+`<section class="panel"><div class="panel-head between"><h3>发布单知识范围</h3>${pill('配置说明视图','blue')}</div><div class="table-wrap"><table><thead><tr><th>知识库</th><th>关联对象</th><th>用途</th><th>可用状态</th></tr></thead><tbody><tr><td>产品发布管理规范</td><td>产品发布主单</td><td>发布要求、提单说明、规则依据</td><td>${pill('示例关联','green')}</td></tr><tr><td>软件包发布说明</td><td>模块发布单、软件物料</td><td>软件用途、版本说明</td><td>${pill('示例关联','green')}</td></tr><tr><td>产品资料维护指引</td><td>产品型号、整机物料</td><td>资料补齐流程与处理入口</td><td>${pill('示例关联','green')}</td></tr></tbody></table></div><div class="panel-body">${inf('文档检索用于解释规则及操作方法。BOM 发布状态、认证有效期等业务事实仍由相应权威接口获取，不从文档中推测。')}<div class="section-gap">${btn('打开问答调试','to-chat','','chat')}</div></div></section>`}
function chatPage(){return header('问答调试','带着具体发布单提问，答案展示事实来源、规则版本和问题位置。','','CONTEXTUAL ASSISTANT')+`<section class="panel chat-layout"><aside class="chat-side"><h3 style="margin-bottom:22px">当前单据数据</h3><dl class="kv" style="grid-template-columns:1fr;gap:6px"><dt>发布单</dt><dd>REL-2026-0108</dd><dt>整机物料</dt><dd>MAT-20260081</dd><dt>发布区域</dt><dd>欧洲</dd><dt>知识范围</dt><dd>产品发布管理规范</dd></dl><hr class="divider"><div class="stack"><button class="btn sm" data-action="ask-preset" data-text="为什么这个发布单不能提交？">为什么不能提交？</button><button class="btn sm" data-action="ask-preset" data-text="Mapping 应该关联什么？">Mapping 如何关联？</button></div></aside><div class="chat-main"><div class="note">${icon('chat')}<span>此处为预设问答交互，未连接大模型。可以体验“为什么不能提交”及 Mapping 说明。</span></div><div class="section-gap">${state.chat.map(m=>`<div class="chat-message ${m.user?'user':''}">${m.html||esc(m.text)}</div>`).join('')}</div><div class="chat-input"><input id="chat-question" aria-label="输入问题" placeholder="试试：这个发布单为什么不能提交？"><button class="btn primary" data-action="ask">发送</button></div></div></section>`}
const connections=[['PIS 主数据','Oracle · PIS_READONLY','数据库','整机物料、产品型号','30 分钟同步'],['IRDMS 研发管理','Oracle · IRDMS_READONLY','数据库','发布主单、发布项、子单、Mapping','按需 / 定时'],['PLM 业务接口','BOM / 零部件发布状态','API','整机物料','按需实时'],['产品认证接口','认证区域、状态、有效期','API','产品认证','按需实时'],['软管平台接口','软件包与软件属性','API','软件物料、模块发布单','按需实时']];
function connectionsPage(){return header('连接管理','维护可复用的技术连接。创建对象时也可以在向导中新增连接。',btn('测试连接','test-connections','','refresh'),'PLATFORM CONNECTIONS')+`<section class="panel"><div class="panel-head between"><h3>共享数据连接</h3>${pill('连接维护视图','blue')}</div><div class="table-wrap"><table><thead><tr><th>连接名称 / 用途</th><th>类型</th><th>引用对象</th><th>取数方式</th><th>状态</th></tr></thead><tbody>${connections.map(c=>`<tr><td class="field-name">${c[0]}<small>${c[1]}</small></td><td>${c[2]}</td><td>${c[3]}</td><td>${c[4]}</td><td>${pill('模拟可用','green')}</td></tr>`).join('')}</tbody></table></div><div class="panel-body">${inf('原 Provider 的端点、鉴权和 MCP 配置归入共享连接。对象属性页负责配置查询参数与响应对应关系；凭据不进入本原型。')}</div></section>`}
function domainsPage(){return header('业务域','区分公共对象与业务专属模型，统一控制引用范围。','','BUSINESS DOMAINS')+`<section class="panel"><div class="panel-head"><h3>业务域设置 · 说明视图</h3></div><div class="table-wrap"><table><thead><tr><th>业务域</th><th>标识</th><th>可见范围</th><th>对象数</th><th>状态</th></tr></thead><tbody><tr><td>公共域</td><td><code>COMMON</code></td><td>跨业务域共享主数据对象</td><td>${objects.filter(o=>o.domain==='COMMON').length}</td><td>${pill('启用','green')}</td></tr><tr><td>项目管理域</td><td><code>BASELINE</code></td><td>研发项目及发布应用，可引用公共对象</td><td>${objects.filter(o=>o.domain==='BASELINE').length}</td><td>${pill('启用','green')}</td></tr></tbody></table></div><div class="panel-body">${inf('左侧业务域选择用于对象目录筛选。公共对象在项目管理域仍然可引用；原型不模拟真实账号权限。')}</div></section>`}

// 统一抽屉：编辑只作用于副本，点击保存才更新工作区。
const overlayRoot=document.getElementById('overlay-root');
let lastFocus=null,toastTimer;
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function options(values,current){return values.map(v=>{const [val,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(val)}" ${String(current)===String(val)?'selected':''}>${esc(label)}</option>`}).join('')}
function field(label,key,value='',kind='text',list=[],help='',wide=false){return `<div class="form-field ${wide?'wide':''}"><label for="f-${key}">${label}</label>${kind==='select'?`<select id="f-${key}" data-field="${key}">${options(list,value)}</select>`:kind==='textarea'?`<textarea id="f-${key}" data-field="${key}">${esc(value)}</textarea>`:`<input id="f-${key}" data-field="${key}" type="${kind}" value="${esc(value)}" autocomplete="off">`}${help?`<small>${help}</small>`:''}</div>`}
function jsonView(v){return `<pre class="json">${esc(JSON.stringify(v,null,2))}</pre>`}
function openDrawer(type,draft={},extra={}){lastFocus=document.activeElement;state.drawer={type,draft:structuredClone(draft),dirty:false,tested:false,error:'',...extra};drawOverlay();focusOverlay()}
function focusOverlay(){const root=overlayRoot.querySelector('[role=dialog]');(root?.querySelector('input:not([type=checkbox]),select,textarea')||root?.querySelector('button'))?.focus()}
function closeOverlay(force=false){if(!force&&(state.drawer?.dirty||state.wizard?.dirty)){const host=overlayRoot.querySelector('.drawer-foot');if(host){host.innerHTML=`<span class="tiny" style="color:var(--amber)">关闭将丢弃尚未保存的编辑。</span><div class="row">${btn('继续编辑','keep-editing')}${btn('丢弃并关闭','discard-edit','danger')}</div>`;host.querySelector('button')?.focus()}return}state.drawer=null;state.wizard=null;overlayRoot.innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function frame(title,sub,body,foot='',wide=false){return `<div class="overlay"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="drawer-body">${state.drawer?.error?`<div class="error" role="alert">${esc(state.drawer.error)}</div>`:''}${body}</div><footer class="drawer-foot"><small>交互原型 · ${state.drawer?.readonly?'只读示例':'保存仅影响当前会话'}</small><div class="row">${btn(state.drawer?.readonly?'关闭':'取消','close')}${foot}</div></footer></section></div>`}
function drawOverlay(){document.body.style.overflow='hidden';if(state.wizard){overlayRoot.innerHTML=wizardView();return}if(!state.drawer)return;const views={prop:propDrawer,relation:relationDrawer,binding:bindingDrawer,rule:ruleDrawer,validate:validateDrawer,smart:smartDrawer,strategy:strategyDrawer,action:actionDrawer,guide:guideDrawer,changes:changesDrawer,checkRelease:checkReleaseDrawer,log:logDrawer,instance:instanceDrawer,testObject:testObjectDrawer};overlayRoot.innerHTML=views[state.drawer.type]?.()||''}
function propDrawer(){const d=state.drawer,p=d.draft;const api=p.source.includes('接口'),db=p.source.includes('数据库');return frame(d.index===-1?'添加业务属性':`配置属性 · ${esc(p.name)}`,`${esc(obj().name)} / ${esc(p.id||'新属性')} · 数据来源`,`${inf('数据数据来源回答“属性的值从哪里来”。表单位置在应用字段绑定中单独配置。')}<div class="form-grid section-gap">${field('属性中文名 *','name',p.name)}${field('属性英文代号 *','id',p.id,'text',[],'英文、数字和下划线，需以字母开头')}${field('数据类型','type',p.type,'select',['文本','枚举','布尔','日期','数字','引用'])}${field('权威来源','source',p.source,'select',[...new Set(['PIS 数据库','IRDMS 数据库','PLM 实时接口','认证实时接口','软管平台接口','用户输入','计算值',p.source])])}${field(api?'接口返回字段的位置 *':db?'源表与字段 *':'字段 / 表达式 *','path',p.path,'text',[],api?'示例：result.certification.status':db?'示例：PIS_MATERIAL.MATERIAL_CODE':'仅作为模拟配置，不执行任意代码',true)}${api?field('请求参数名','parameter',p.parameter||'materialCode')+field('参数值取自','parameterFrom',p.parameterFrom||'Material.materialCode','select',objects.flatMap(o=>o.props.map(p=>[`${o.id}.${p.id}`,`${o.name}.${p.name}`]))):''}${field('空值处理','nullPolicy',p.nullPolicy||'返回未知，不填默认值','select',['返回未知，不填默认值','保留已有值','提示用户补齐'])}${field('值转换','conversion',p.conversion||'保持原值','select',['保持原值','去除首尾空格','转换为文本','枚举：Y/N → 是/否'])}${field('示例源值','sample',p.sample??String(p.value??''),'text',[],'可修改示例值验证类型与空值处理')}${field('数据更新时间','freshness',p.freshness||(api?'提交时重新查询':'每 30 分钟同步'),'select',api?['提交时重新查询','按需查询，缓存 60 秒']:['每 30 分钟同步','每日同步','仅手动同步'])}</div><div class="row section-gap" style="flex-wrap:wrap">${['key','display','required'].map((k,i)=>`<label class="check-row"><input type="checkbox" data-check="${k}" ${p[k]?'checked':''}>${['记录的唯一编号','列表显示名称','必填'][i]}</label>`).join('')}</div><div class="section-gap between"><h3>对应关系测试</h3>${btn('测试此对应关系','test-prop','sm','play')}</div>${d.tested?`<div class="test-result">${inf(`测试通过：源值 <code>${esc(p.sample??p.value)}</code> → <code>${esc(d.output)}</code> → 业务属性 <code>${esc(p.id)}</code>，类型 ${esc(p.type)}。`,'green')}</div>`:d.testError?`<div class="test-result">${inf(esc(d.testError),'red')}</div>`:'<p class="session-note">修改配置后需重新测试，测试通过才能保存。</p>'}`,btn('保存属性配置','save-prop','primary','check'));}
function relationDrawer(){const d=state.drawer,r=d.draft;return frame(d.index===-1?'添加业务关系':`配置关系 · ${esc(r.name)}`,'业务业务含义与数据关联方式在同一个编辑器中完成。',`<div class="form-grid">${field('关系名称 *','name',r.name,'text',[],'使用“包含”“发布目标”等业务动词',true)}${field('源对象','from',r.from,'select',objects.map(o=>[o.id,o.name]))}${field('目标对象','to',r.to,'select',objects.map(o=>[o.id,o.name]))}${field('关系基数','card',r.card,'select',['一对多（1:N）','多对一（N:1）','一对一（1:1）','多对多（N:N）'])}${field('数据关联方式','method',r.method,'select',['字段关联','中间表','API 查询','身份引用'])}${field('源对象属性','left',r.left,'select',obj(r.from)?.props.map(p=>[p.id,p.name])||[])}${field('目标对象属性','right',r.right,'select',obj(r.to)?.props.map(p=>[p.id,p.name])||[])}${r.method==='中间表'?field('关联表','joinTable',r.joinTable||'RELEASE_MAPPING')+field('关联条件','joinOn',r.joinOn||'RELEASE_ITEM_ID → RELEASE_ITEM.ID'):''}${r.method==='API 查询'?field('数据查询','api',r.api||'按业务编码查询关联对象','text',[],'从共享连接选择查询；参数由源对象属性提供',true):''}</div><div class="section-gap">${inf('Mapping 引用整机发布项时，使用 releaseItemRef → releaseItemId；不能替换为物料编码。','amber')}</div><div class="section-gap between"><h3>关联测试</h3>${btn('测试关联','test-relation','sm','play')}</div>${d.tested?`<div class="test-result">${inf(`示例匹配通过：${esc(name(r.from))}.${esc(r.left)} → ${esc(name(r.to))}.${esc(r.right)}。`,'green')}<div class="sample section-gap">命中：1 条　未命中：0 条　歧义：0 条<br>这是单条样例检查；生产环境仍需检查全量重复值和基数。</div></div>`:''}`,btn('保存关系','save-relation','primary','check'));}
function bindingDrawer(){const d=state.drawer,b=d.draft;return frame(d.index===-1?'添加应用字段绑定':`配置填入规则 · ${esc(b.label)}`,`产品发布单 / ${blockNames[state.block]} / V3`,`${inf('业务对象提供属性业务含义，绑定配置确定表单区块、行上下文及 API 字段。')}<div class="form-grid section-gap">${field('目标字段名称 *','label',b.label)}${field('目标字段 / API 路径 *','target',b.target,'text',[],state.block==='main'?'主单字段使用 mainOrder. 前缀':'明细字段需包含 []，表示逐行上下文')}${field('业务属性 *','ontology',b.ontology,'select',objects.flatMap(o=>o.props.map(p=>[`${o.id}.${p.id}`,`${o.name} / ${p.name} · ${p.id}`])),null,true)}${field('取值方式','method',b.method,'select',['用户表达 / 智能建议','项目上下文','用户输入','PIS 核实后填写','关联整机物料','业务接口生成','软管平台查询','软件包属性','引用当前主单发布行','引用当前主单子单','软件用途 / 用户输入'])}${field('数据方向','direction',b.direction,'select',['建议写入','只读','双向','引用绑定'])}${field('已有值处理','policy',b.policy,'select',['保留用户修改','差异确认','刷新来源值','保持稳定引用'])}${field('空值处理','nullPolicy',b.nullPolicy||'保留空值并提示','select',['保留空值并提示','保留已有值'])}</div><div class="mini-flow section-gap"><b>${esc(semanticPath(b.ontology))}</b>${icon('arrow')}<span>${esc(b.target)}</span></div>${state.block==='mapping'?inf('引用字段需绑定稳定的行 ID。示例展示 MAT-20260081，实际保存 RI-001。','amber'):inf('用户修改过的值在重新生成建议时保留，不能静默覆盖。')}<div class="between section-gap"><h3>单字段绑定预览</h3>${btn('测试绑定','test-one-binding','sm','play')}</div>${d.tested?`<div class="test-result">${jsonView({[b.target]:getValue(b.ontology)})}</div>`:''}`,btn('保存字段绑定','save-binding','primary','check'),true);}
function strategyDrawer(){const d=state.drawer,s=d.draft;return frame('对象数据更新方式',`${obj().name} · 稳定属性同步，最新业务数据按需获取。`,`<div class="form-grid">${field('稳定属性获取方式','stable',s.stable,'select',['每 30 分钟同步','每日同步','仅手动同步'])}${field('最新业务数据获取方式','dynamic',s.dynamic,'select',['提交时重新查询','按需查询，缓存 60 秒'])}${field('源系统超时','timeout',s.timeout,'select',['返回未能取得数据','重试 1 次后返回未知'])}${field('对象主键重复','duplicate',s.duplicate,'select',['阻止发布配置并提示','隔离重复数据后人工处理'])}</div><div class="section-gap">${inf('配置同步策略不会立即清空或写入图数据库。BOM、认证等最终提交事实需要按规则要求重新获取。')}</div>`,btn('保存数据更新方式','save-strategy','primary','check'));}
function getValue(ontology){if(ontology==='ReleaseOrder.releaseSubject')return state.subject;const [o,p]=ontology.split('.');return obj(o)?.props.find(x=>x.id===p)?.value??null}
function buildPayload(){const payload={};Object.values(bindings).flat().forEach(b=>{const [section,key]=b.target.split('.');if(!key)return;const val=getValue(b.ontology);if(section.endsWith('[]')){const n=section.slice(0,-2);payload[n]??=[{}];payload[n][0][key]=val;}else{payload[section]??={};payload[section][key]=val;}});return payload}
function actionDrawer(){const d=state.drawer,i=d.index,a=actions[i];return frame(a[0],a[1],`<div class="sample"><strong>业务接口（示例）</strong><br><code>${a[2]}</code></div><dl class="kv section-gap"><dt>应用 / 表单</dt><dd>产品发布单 / V3</dd><dt>执行权限</dt><dd>${i===4?'具有提交权限的当前用户':'当前业务用户'}</dd><dt>确认方式</dt><dd>${i===4?'用户确认后，后端终检通过再提交':'保留用户对建议及草稿的控制'}</dd><dt>业务约束</dt><dd>校验单据版本、引用完整性和字段权限</dd></dl><hr class="divider"><h3 style="margin-bottom:16px">${i===0?'示例读取结果':'输入结构预览'}</h3>${jsonView({releaseOrderId:'REL-2026-0108',documentVersion:3,...buildPayload()})}<div class="section-gap">${inf('此页展示动作配置。真实接口、鉴权、事务和幂等需由生产系统实现。')}</div>`,i===1?btn('体验填单建议','smart-draft','primary','play'):i===2?btn('模拟保存草稿','save-form','primary','file'):i>=3?btn('调试执行','validate','primary','play'):'',true);}
function resultFor(i){const r=rules[i];if(i===0&&!state.repaired)return {status:'阻断',detail:'IPC-A400-EU 已进入商品目录，但缺少产品正面图片。',proof:'PIS · modelCode=IPC-A400-EU · hasImage=false',color:'red'};if(i===1&&state.timeout)return {status:'未知',detail:'PLM 查询超时，暂时无法确认受控零部件的发布状态。',proof:'PLM · materialCode=MAT-20260081 · 模拟超时',color:'amber'};return {status:'通过',detail:['图片、规格、功能特性和资料均已齐备。','3 个受控零部件均为已发布。','CE 认证覆盖欧洲，有效期至 2027-08-31。','RI-001 和 MO-001 均属于当前主单，软件引用一致。'][i],proof:[`PIS · hasImage=${state.repaired} · modelCode=IPC-A400-EU`,'PLM · BOM 版本 B3 · controlledParts=3','产品认证 · CERT-EU-026 · status=VALID','当前单据 · releaseItemRef=RI-001 · moduleOrderRef=MO-001'][i],color:'green'};}
function validationResults(){return rules.slice(0,4).map((r,i)=>({rule:r,index:i,...resultFor(i)})).filter(x=>x.rule.enabled!==false).map(x=>x.status==='阻断'&&x.rule.level==='警告'?{...x,status:'警告',color:'amber'}:x)}
function canSubmit(){return state.checked&&!validationResults().some(x=>x.status==='阻断'||x.status==='未知')}
function ruleDrawer(){const d=state.drawer,r=d.draft;const read=d.index===4;return frame(read?'待确认 · 项目 DI 发布条件':`配置规则 · ${esc(r.name)}`,`${r.id} · ${r.version} · 触发于预校验和最终提交`,read?`${inf('此规则保持未启用。需要先由业务确认 DI 汇总口径、缺陷范围、统计时间及发布阈值，不能使用示例数值作为正式门禁。','amber')}<dl class="kv section-gap"><dt>事实来源</dt><dd>IRDMS 缺陷单</dd><dt>待确认内容</dt><dd>项目范围、缺陷类型、DI 计算口径、阈值和豁免权限</dd><dt>当前状态</dt><dd>未启用，不参与模拟校验</dd></dl>`:`<div class="form-grid">${field('规则名称 *','name',r.name,'text',[],'规则判断使用当前演示模板',true)}${field('适用条件','condition',r.condition,'text',[],null,true)}${field('所需事实','fact',r.fact,'text',[],null,true)}${field('判断要求','judge',r.judge,'text',[],'此原型展示配置；可执行逻辑使用该规则的内置样例模板',true)}${field('严重级别','level',r.level,'select',['阻断','警告'])}${field('事实来源','source',r.source)}${field('失败定位','field',r.field,'text',[],'返回区块、行和字段，便于发布单页面定位',true)}${field('测试样例','sampleCase',r.sampleCase||'业务不满足','select',['业务不满足','满足条件','接口超时'])}</div><hr class="divider"><div class="between"><h3>模板样例测试</h3>${btn('运行测试','test-rule','sm','play')}</div>${d.tested?`<div class="test-result">${inf(r.sampleCase==='接口超时'?'样例结果：未能取得数据。必要事实未获取，不能判为通过。':r.sampleCase==='满足条件'?'样例结果：通过。所需事实满足该规则模板。':`样例结果：${r.level}。定位至 ${esc(r.field)}。`,r.sampleCase==='满足条件'?'green':r.sampleCase==='接口超时'?'amber':'red')}</div>`:'<p class="session-note">可测试三种结果，避免把源系统异常与业务不满足混为一类。</p>'}`,read?'':btn('保存规则配置','save-rule','primary','check'),true);}
function validateDrawer(){const d=state.drawer;const results=validationResults();const blocked=results.filter(x=>x.status==='阻断').length,unknown=results.filter(x=>x.status==='未知').length;const success=state.checked&&!blocked&&!unknown;let body=`<div class="sample"><div class="between"><strong>REL-2026-0108 · ${esc(state.subject)}</strong>${pill(state.submitted?'已模拟提交':'现有草稿',state.submitted?'green':'blue')}</div><span class="muted">整机 MAT-20260081　·　软件 SW-20260032　·　发布区域 欧洲</span></div><div class="between section-gap"><h3>提交前校验</h3><label class="check-row"><input type="checkbox" data-validate-timeout ${state.timeout?'checked':''}>模拟 PLM 超时</label></div>`;
if(!state.checked)body+=`<div class="empty">${icon('shield')}<b>获取事实后执行规则</b>点击“执行预校验”查看缺失资料、BOM 状态、认证及引用检查。<br>修复或修改数据后需要重新校验。</div>`;
else body+=`<div class="section-gap">${inf(success?'预校验通过。最终提交仍会重新获取必要事实并由后端终检。':`${blocked} 项阻断 · ${unknown} 项未能取得数据。处理后重新校验。`,success?'green':unknown?'amber':'red')}</div>${results.map(x=>`<div class="result-card ${x.status==='通过'?'pass':x.status==='未知'?'unknown':'fail'}" id="result-${x.index}"><div class="result-head"><div class="row"><strong>${x.rule.name}</strong>${pill(x.status,x.color)}</div><span class="muted tiny">${x.rule.id} · ${x.rule.version}</span></div><p>${x.detail}</p><div class="proof">${esc(x.proof)} · ${state.checkedAt||now()}</div>${x.status!=='通过'?`<div class="between" style="margin-top:10px"><button class="link" data-action="locate-issue" data-index="${x.index}">定位：${esc(x.rule.field)}</button>${x.index===0?btn('补齐图片（模拟）','repair','sm','refresh'):btn('关闭超时并重试','retry-plm','sm','refresh')}</div>`:''}${d.issue===x.index?`<div class="note section-gap">${icon('info')}<span>问题位置：${esc(x.rule.field)}<br>源系统：${esc(x.rule.source)}。生产页面可据此定位行和字段，并跳转对应处理入口。</span></div>`:''}</div>`).join('')}`;
if(d.confirm)body+=`<div class="note amber section-gap">${icon('info')}<span><strong>确认模拟提交</strong><br>提交主单 REL-2026-0108，包含发布项 RI-001、模块子单 MO-001、Mapping MP-001。确认后重新终检，记录本次提交结果。</span></div>`;
if(state.submitted)body+=`<div class="note green section-gap">${icon('check')}<span>模拟提交完成。已记录单据版本、引用、规则版本和事实来源；未向真实系统发送请求。</span></div>`;
const foot=state.submitted?btn('查看执行记录','to-runs','primary','clock'):(d.confirm?btn('确认模拟提交','confirm-submit','primary','upload'):btn(state.checked?'重新预校验':'执行预校验','run-validation','','shield')+btn('模拟提交','submit','primary','upload',!canSubmit()?'disabled':''));return frame('发布单校验与提交','当前业务数据为模拟样例。补齐资料后可体验完整提交过程。',body,foot,true);}
function smartDrawer(){const d=state.drawer;return frame('智能提单 · 建议预览','输入业务需求，将内容放入对应的主单、子单及 Mapping 区块。',`<div class="form-grid">${field('发布需求','request',d.draft.request||'给项目 PRJ-2026-A 创建欧洲发布单，整机 MAT-20260081，软件 SW-20260032，发布主题为“欧洲版主程序升级”。','textarea',[],'本原型识别当前示例项目、物料和软件；其他编码会提示不支持，不调用大模型。',true)}</div><div class="between section-gap"><span class="tiny muted">通过业务对象确认对象，再应用字段绑定</span>${btn('生成建议','generate-smart','sm','bind')}</div>${d.generated?`<hr class="divider">${d.subjectEdited?inf(`已保留用户修改。此次推荐主题：${esc(d.suggestedSubject||state.subject)}`,'amber'):''}<div class="form-grid">${field('发布主题（可修改）','subject',d.draft.subject||state.subject,'text',[],'手工修改后保存时将保留该值',true)}</div><div class="section-gap">${jsonView({...buildPayload(),mainOrder:{...(buildPayload().mainOrder||{}),releaseSubject:d.draft.subject||state.subject}})}</div><div class="section-gap">${inf('建议已按四个区块组织。Mapping 保存 RI-001 和 MO-001 的引用，用户确认后通过业务接口保存草稿。','green')}</div>`:''}`,d.generated?btn('确认并模拟保存草稿','save-smart','primary','file'):'',true);}
function testObjectDrawer(){const o=obj();return frame('对象对应关系测试',`${o.name} · 检查属性身份、来源及类型`,`${inf('本次基于当前配置和单条示例值检查，不代表已验证真实数据库。','green')}<div class="section-gap">${o.props.map(p=>`<div class="release-line"><div class="release-check">${icon('check')}</div><div class="fill"><h4>${esc(p.name)} <code>${esc(p.id)}</code></h4><p>${esc(p.path)} → ${esc(p.value)}</p></div>${pill(p.key?'唯一编号':'对应关系通过','green')}</div>`).join('')}</div><div class="section-gap">${btn('打开数据预览','preview-tab','','eye')}</div>`,'',true);}
function guideDrawer(){return frame('演示指南','建议沿着以下路径体验，所有操作均为模拟。',`${inf('数据保存在页面内存中，刷新会重置。可以通过运行记录导出本次操作。')}<div class="guide-list">${[['统一对象入口','在对象与数据中点击“添加业务对象”，选择 IRDMS 或 PIS，选表、确认主键、编辑字段并保存草稿。','objects'],['属性取数对应关系','在对象属性表点击“配置”，体验数据库/API 来源、查询条件取值、转换及测试。','objects'],['应用字段绑定','切换主单、发布清单、子单及 Mapping，查看业务属性如何对应到表单与 API 路径。','bindings'],['智能提单','进入业务动作，生成建议；可以修改发布主题，然后确认保存模拟草稿。','actions'],['校验、修复与提交','在校验规则中调试发布单，补齐模拟图片并重新校验，再确认模拟提交。也可勾选 PLM 超时。','rules'],['发布配置并追溯','检查配置包、发布模拟版本，再到运行记录查看参数、规则和执行结果。','release']].map(([t,p,r])=>`<div class="guide-item"><div class="fill"><h3>${t}</h3><p>${p}</p></div><button class="link" data-action="guide-route" data-route="${r}">前往</button></div>`).join('')}</div>`,'',true);}
function changesDrawer(){return frame('本次调整点','基于现有平台截图，梳理入口、业务逻辑及新增页面。',`<div class="guide-list">${[['合并对象与数据接入','原“数据 → 节点对应关系”和“资产 → 对象”串成同一工作流，创建对象时选择连接、表、主键与字段。'],['补齐两类对应关系','对象内配置数据库/API → 业务属性；应用配置内新增业务属性 → 表单/API 字段，明确各自职责。'],['明确对象身份','记录的唯一编号与列表显示名称分开设置；对象不等于一张数据库表，可组合多个数据来源。'],['关系先讲业务含义','属性匹配和中间表变为关联方式，关系定义先选择源对象、业务动词、目标及基数。'],['发布单按区块绑定','明确主单、发布项、模块子单及 Mapping 的上下文，Mapping 使用发布行 ID，避免同物料多行歧义。'],['最新业务数据与确定性规则','BOM、认证等按需查询，超时返回未知；规则给出结论、证据、问题位置和修复入口。'],['草稿、发布与执行分离','保存配置仅修改草稿；配置包检查后发布；业务提交单独确认并由后端终检。'],['减少技术术语及跨页切换','固定左侧导航，统一业务域入口；高级参数保留在配置内，主要页面围绕业务对象展开。']].map(([t,p])=>`<div class="guide-item"><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><div class="section-gap"><a class="export-link" href="../业务对象平台优化设计方案.md" target="_blank">${icon('file')}查看完整设计方案</a></div>`,'',true);}
function configErrors(){const errs=[];for(const r of relations){if(!obj(r.from)?.props.some(p=>p.id===r.left)||!obj(r.to)?.props.some(p=>p.id===r.right))errs.push(`${r.name} 引用了不存在的对象属性`);}for(const o of objects){if(o.props.filter(p=>p.key).length!==1)errs.push(`${o.name} 必须有且仅有一个唯一编号`);if(new Set(o.props.map(p=>p.id)).size!==o.props.length)errs.push(`${o.name} 存在重复属性英文代号`);o.props.forEach(p=>{if(!p.path)errs.push(`${o.name}.${p.id} 缺少数据来源`)})}for(const [block,list]of Object.entries(bindings)){if(new Set(list.map(b=>b.target)).size!==list.length)errs.push(`${blockNames[block]} 存在重复目标字段`);for(const b of list){const [o,p]=b.ontology.split('.');if(!obj(o)?.props.some(x=>x.id===p))errs.push(`${b.label} 引用了不存在的属性`)}}return errs}
function checkReleaseDrawer(){const errs=configErrors();return frame('配置检查结果','模型、数据来源、关系和应用字段引用一致性检查。',`${inf(errs.length?`发现 ${errs.length} 个问题，请处理后发布。`:'当前配置检查通过，可以发布模拟配置包。',errs.length?'red':'green')}${errs.length?`<div class="sample section-gap">${errs.map(esc).join('<br>')}</div>`:`<ul class="checklist section-gap"><li>${icon('check')}对象主键完整且无重复属性</li><li>${icon('check')}业务属性具有来源路径</li><li>${icon('check')}应用字段引用有效、目标字段无重复</li><li>${icon('check')}Mapping 的行引用保持稳定</li></ul>`}<div class="section-gap">${inf('检查使用示例数据；生产环境仍需接口连通性、权限、批量数据质量和真实场景回放验证。')}</div>`,errs.length?'':btn('发布模拟配置包','publish','primary','upload'));}
function logDrawer(){const l=state.logs[state.drawer.index];return frame('执行详情',`${l.time} · ${l.type} · ${l.title}`,`<dl class="kv"><dt>结果</dt><dd>${pill(l.result,l.result==='通过'||l.result==='成功'?'green':'amber')}</dd><dt>执行详情</dt><dd>${esc(l.detail)}</dd><dt>执行环境</dt><dd>本地交互原型 · 模拟执行</dd><dt>配置版本</dt><dd>release-app-v${l.configVersion}.0</dd></dl><div class="section-gap">${l.evidence?jsonView(l.evidence):inf('此记录用于展示操作追溯；没有向公司数据库或接口发起请求。')}</div>`);}
function instanceDrawer(){const o=obj(state.drawer.object||'ReleaseOrder');return frame(`示例记录 · ${esc(o.name)}`,'只读记录详情与来源摘要。',`<dl class="kv">${o.props.map(p=>`<dt>${esc(p.name)}</dt><dd>${esc(p.value)}<br><code>${esc(p.path)}</code></dd>`).join('')}</dl><div class="section-gap">${inf('模型定义与业务记录分开浏览；此处所有值来自原型内置样例。')}</div>`);}

