function wizardSourcePreview(){const s=wizardSchema();return s?`<section class="wizard-source-preview section-gap"><div class="between"><h3>表里有哪些字段和数据</h3>${pill('已选择来源','blue')}</div><p class="tiny muted section-gap">来源表：<code>${esc(s.table)}</code> · 表注释：${esc(s.name)} · ${s.fields.length} 个字段</p><div class="table-wrap section-gap"><table><thead><tr><th>来源字段</th><th>字段说明</th><th>类型</th><th>样例值</th></tr></thead><tbody>${s.fields.map(f=>`<tr><td><code>${esc(f[0])}</code></td><td>${esc(f[1])}</td><td>${esc(f[4])}</td><td>${esc(f[3])}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted section-gap">内置结构与样例，仅用于理解来源。下一步单独定义业务对象及属性。</p></section>`:'<div class="sample section-gap">请输入或搜索表名，点击来源表后查看字段和样例。</div>';}
function wizardView(){const w=state.wizard;let content='';if(w.step===0){content=`<div class="choice-row">${[['db','数据库来源','db'],['api','从 API 接入','link'],['manual','手工定义对象','edit']].map(([id,t,ic])=>`<button class="choice ${w.mode===id?'active':''}" data-action="wizard-mode" data-mode="${id}">${icon(ic)}${t}</button>`).join('')}</div>`;
if(w.mode==='db')content+=`<div class="between" style="margin-bottom:12px"><h3>选择数据库连接</h3><button class="link" data-action="new-connection">${w.newConnection?'使用已有连接':'＋ 在此新增连接'}</button></div>${w.newConnection?`<div class="sample"><div class="form-grid">${wField('连接名称 *','connName',w.connName||'研发数据连接')}${wField('数据库类型','connType',w.connType||'Oracle','select',['Oracle','MySQL','PostgreSQL'])}${wField('主机地址（演示） *','host',w.host||'demo-db.internal')}${wField('端口','port',w.port||'1521')}${wField('数据库 / 服务名 *','database',w.database||'IRDMS_DEMO')}${wField('Schema','schema',w.schema||'READONLY')}${wField('用户名（演示）','user',w.user||'prototype_readonly')}${wField('密码（请勿填写真实凭据）','password','', 'password')}</div><div class="between section-gap"><label class="check-row"><input type="checkbox" data-wcheck="connectionFailure" ${w.connectionFailure?'checked':''}>模拟连接失败</label>${btn(w.connectionTested?'测试连接通过':'测试连接','wizard-test-connection','sm','refresh')}</div>${w.connectionTested?`<div class="section-gap">${inf('模拟连接成功，已加载内置样例。不会发送网络请求。','green')}</div>`:''}</div>`:`<div class="form-field"><label for="wizard-connection">数据库连接</label><select id="wizard-connection" data-wfield="connection">${options([['IRDMS','IRDMS 研发管理 · Oracle'],['PIS','PIS 主数据 · Oracle']],w.connection)}</select><small>已有连接直接复用，无需离开当前页面。</small></div>`}<div class="section-gap">${inf('先选择数据来源，再定义业务对象。来源表提供字段和记录，一个业务对象可通过多个数据查询接入不同来源。')}</div><div class="between section-gap" style="margin-bottom:12px"><h3>选择来源表 / 视图</h3><span class="muted tiny">内置样例</span></div><div class="search">${icon('search')}<input placeholder="输入表名或中文注释，如 RELEASE_BATCH" aria-label="输入或搜索来源表名" data-wfield="tableQuery" value="${esc(w.tableQuery)}"></div><div id="wizard-tables">${wizardTableList()}</div>${wizardSourcePreview()}`;
else if(w.mode==='api')content+=wizardApiSourceView();
else content+=`${inf('先定义业务对象、唯一编号和必要属性，不要求先有数据库表。默认使用用户输入来源，后续可补充接口或数据库对应关系。')}<div class="section-gap sample">默认提供编号、名称和状态三个候选属性；下一步可调整名称和选择需要的属性。</div>`;
}else if(w.step===1){const existing=w.objectAction==='existing',target=objects.find(o=>o.id===w.existingObject);content=`${inf(w.mode==='manual'?'按业务含义定义对象和属性。':`已选来源：<code>${esc(wizardSchema().table)}</code>。请单独选择要表达的业务对象，表注释不会自动填入对象名称。`)}<div class="choice-row section-gap">${[['new','新建业务对象'],...(w.mode==='manual'?[]:[['existing','给已有对象添加数据来源']])].map(([id,label])=>`<button class="choice ${w.objectAction===id?'active':''}" data-action="wizard-object-action" data-mode="${id}">${icon(id==='new'?'plus':'link')}${label}</button>`).join('')}</div>${existing?`<div class="form-grid">${wField('选择已有业务对象 *','existingObject',w.existingObject,'select',[['','请选择业务对象'],...objects.map(o=>[o.id,`${o.name} · ${o.id}`])])}</div>${target?`<div class="sample section-gap">业务对象：<b>${esc(target.name)}</b> · <code>${esc(target.id)}</code><br>唯一编号：${esc(target.props.find(p=>p.key)?.name||'未配置')} · 已有 ${target.props.length} 项属性<br>只新增一项数据查询，已有对象和属性不变。</div>`:''}`:`<div class="form-grid">${wField('业务对象名称 *','objectName',w.objectName,'text',[])}${wField('业务对象英文代号 *','objectId',w.objectId)}${wField('归属业务域','domain',w.domain,'select',[['BASELINE','项目管理域'],['COMMON','公共域']])}${wField('记录的唯一编号 *','key',w.key,'select',w.fields.map(f=>[f.id,f.name]))}${wField('列表显示名称','display',w.display,'select',w.fields.map(f=>[f.id,f.name]))}</div><p class="tiny muted section-gap">请按业务含义命名，例如“发布批次”；对象英文代号例如 ReleaseBatch。唯一编号用于识别具体记录。</p>`}<div class="between section-gap" style="margin-bottom:10px"><h3>${w.mode==='manual'?'选择业务属性':'选择参与对应关系的来源字段'}</h3><span class="muted tiny">${existing?'下一步确认目标属性':'只勾选需要的字段'}</span></div><div class="table-wrap"><table><thead><tr><th>纳入</th><th>来源字段</th><th>字段说明</th><th>样例值</th></tr></thead><tbody>${w.fields.map((f,i)=>`<tr><td><input type="checkbox" data-winclude="${i}" aria-label="纳入 ${esc(f.name)}" ${f.include?'checked':''} ${!existing&&f.id===w.key?'disabled':''}></td><td><code>${esc(f.column)}</code></td><td>${esc(f.name)}</td><td class="muted">${esc(f.sample)}</td></tr>`).join('')}</tbody></table></div>`;
}else if(w.step===2){const existing=w.objectAction==='existing',target=objects.find(o=>o.id===w.existingObject);content=`<div class="mini-flow"><span>来源：${esc(wizardSchema().table)}</span>${icon('arrow')}<b>业务对象：${esc(existing?target?.name:w.objectName)}</b></div><div class="table-wrap"><table class="map-table"><thead><tr><th>来源字段</th><th></th>${existing?'<th>对应的业务属性 *</th><th>类型</th>':'<th>业务属性英文代号 *</th><th>中文名 *</th><th>类型</th>'}</tr></thead><tbody>${w.fields.map((f,i)=>f.include?`<tr><td><code>${esc(f.column)}</code><small class="field-path">${esc(f.sample)}</small></td><td class="map-arrow">→</td>${existing?`<td><select aria-label="对应的业务属性 ${i+1}" data-wmap="${i}" data-mapkey="target">${options([['','请选择目标属性'],...(target?.props||[]).map(p=>[p.id,`${p.name} · ${p.id}${p.key?'（唯一编号）':''}`])],f.target)}</select></td><td>${esc(f.type)}</td>`:`<td><input aria-label="属性英文代号 ${i+1}" data-wmap="${i}" data-mapkey="id" value="${esc(f.id)}"></td><td><input aria-label="属性中文名 ${i+1}" data-wmap="${i}" data-mapkey="name" value="${esc(f.name)}"></td><td><select aria-label="属性类型 ${i+1}" data-wmap="${i}" data-mapkey="type">${options(['文本','枚举','布尔','日期','数字','引用'],f.type)}</select></td>`}</tr>`:'').join('')}</tbody></table></div><div class="section-gap">${inf(existing?'同名属性只作建议，请逐项确认。必须选择记录的唯一编号，来源字段与业务属性的数据类型需一致。':'字段说明仅作为属性命名建议，请按业务业务含义调整。保存前检查缺失对应关系、重复标识和数据类型。')}</div>`;
}else{const existing=w.objectAction==='existing',target=objects.find(o=>o.id===w.existingObject);content=`<div class="between" style="margin-bottom:18px"><div><h3>${esc(existing?target?.name:w.objectName)}</h3><code>${esc(existing?target?.id:w.objectId)}</code></div>${pill(existing?'添加数据来源':'新建对象草稿','amber')}</div><div class="sample">来源：<code>${esc(wizardSchema().table)}</code><br>业务对象：${esc(existing?target?.name:w.objectName)}<br>${existing?'保存后给这个对象添加一项数据查询。不会新建对象，也不会改动已有属性。':'保存后创建业务对象及数据来源草稿。'}</div><div class="form-grid section-gap">${wField('数据更新方式','stable',w.stable,'select',w.mode==='api'?['按需实时查询']:w.mode==='manual'?['用户输入']:['每 30 分钟同步','每日同步','仅手动同步'])}</div><div class="section-gap table-wrap"><table><thead><tr><th>来源字段</th><th>对应的业务属性</th><th>源值 → 预览值</th><th>结果</th></tr></thead><tbody>${w.fields.filter(f=>f.include).map(f=>`<tr><td><code>${esc(f.column)}</code></td><td>${esc(existing?target?.props.find(p=>p.id===f.target)?.name:f.name)}<br><code>${esc(existing?f.target:f.id)}</code></td><td>${esc(f.sample)} → ${esc(convertWizardValue(f))}</td><td>${pill(validSample(f.sample,f.type)?'通过':'类型不匹配',validSample(f.sample,f.type)?'green':'red')}</td></tr>`).join('')}</tbody></table></div><div class="between section-gap"><span class="tiny muted">样例验证 · 检查主键及类型</span><label class="check-row"><input type="checkbox" data-wcheck="simulateDuplicate" ${w.simulateDuplicate?'checked':''}>模拟重复主键</label></div><div class="section-gap">${inf(w.simulateDuplicate?'检测到重复主键，不能保存。取消模拟或在源系统修复。':'样例对应关系检查完成。保存为草稿，不会立即同步生产数据，也不会自动绑定应用场景。',w.simulateDuplicate?'red':'green')}</div>`;}
return `<div class="overlay wizard-overlay"><section class="wizard" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><h2 id="dialog-title">添加业务对象</h2><p>选择来源 → 定义业务对象 → 配置设置字段对应关系</p></div><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="wizard-steps">${['选择数据来源','定义业务对象','设置字段对应关系','预览确认'].map((s,i)=>`<div class="wizard-step ${i===w.step?'active':i<w.step?'done':''}"><i>${i<w.step?'✓':i+1}</i>${s}</div>`).join('')}</div><div class="drawer-body">${w.error?`<div class="error" role="alert">${esc(w.error)}</div>`:''}${content}</div><footer class="drawer-foot"><small>步骤 ${w.step+1} / 4 · 使用内置样例</small><div class="row">${btn('取消','close')}${w.step?btn('上一步','wizard-prev'):''}${btn(w.step===3?(w.objectAction==='existing'?'保存数据来源':'保存对象草稿'):'下一步',w.step===3?'wizard-save':'wizard-next','primary',w.step===3?'check':'arrow',w.step===0&&w.mode==='api'&&wizardApiError()?'disabled':'')}</div></footer></section></div>`;}
function wField(label,key,val,kind='text',list=[]){return field(label,key,val,kind,list).replaceAll('data-field=','data-wfield=').replaceAll('id="f-','id="wf-').replaceAll('for="f-','for="wf-')}
function wizardTableList(){const w=state.wizard;const tables=tableSchemas[w.connection==='PIS'?'PIS':'IRDMS'];return tables.map((t,i)=>({...t,index:i})).filter(t=>(t.table+t.name).toLowerCase().includes((w.tableQuery||'').toLowerCase())).map(t=>`<button class="table-choice ${w.tableIndex===t.index?'active':''}" data-action="wizard-table" data-index="${t.index}"><span class="radio-ring"></span><div class="fill"><b><code>${esc(t.table)}</code></b><small>表注释：${esc(t.name)}</small></div><span class="muted tiny">${t.fields.length} 字段</span></button>`).join('')||'<div class="empty">没有匹配的表，请修改搜索词。</div>'}
function validSample(value,type){if(value===null||value===undefined||String(value).trim()==='')return false;if(type==='数字')return Number.isFinite(Number(value));if(type==='布尔')return ['true','false','Y','N','是','否'].includes(String(value));if(type==='日期')return /^\d{4}-\d{2}-\d{2}/.test(String(value))&&!Number.isNaN(Date.parse(value));return true}
function convertWizardValue(f){if(f.type==='数字'&&validSample(f.sample,f.type))return Number(f.sample);if(f.type==='布尔'&&validSample(f.sample,f.type))return ['true','Y','是'].includes(String(f.sample));return f.sample}

function navigate(route){if(!pages[route])return;closeOverlay(true);state.route=route;state.mobile=false;history.replaceState(null,'',`#${route}`);render();window.scrollTo(0,0)}
function errorDrawer(message){state.drawer.error=message;drawOverlay();overlayRoot.querySelector('.drawer-body')?.scrollTo(0,0)}
function errorWizard(message){state.wizard.error=message;drawOverlay();overlayRoot.querySelector('.drawer-body')?.scrollTo(0,0)}
function validProp(p,index){if(!p.name.trim()||!p.path.trim())return '请填写属性名称和来源路径。';if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(p.id))return '属性英文代号需以英文字母开头，仅使用字母、数字和下划线。';if(obj().props.some((x,i)=>i!==index&&x.id===p.id))return '当前对象内已存在相同属性英文代号。';if(index>=0&&obj().props[index].id!==p.id){const old=`${obj().id}.${obj().props[index].id}`;if(Object.values(bindings).flat().some(b=>b.ontology===old)||relations.some(r=>(r.from===obj().id&&r.left===obj().props[index].id)||(r.to===obj().id&&r.right===obj().props[index].id)))return '该属性英文代号被应用或关系引用，请保留标识；可修改属性中文名。';}if(index>=0&&obj().props[index].key&&!p.key)return '该属性是对象的唯一编号。请先为其他属性配置唯一编号，再修改此项。';return ''}
function validBinding(b,index){if(!b.label.trim())return '请填写目标字段名称。';const prefix={main:'mainOrder.',items:'releaseItems[].',modules:'moduleOrders[].',mapping:'mapping[].'}[state.block];if(!b.target.startsWith(prefix)||!/^\w+(?:\[\])?\.[A-Za-z]\w*$/.test(b.target))return `当前区块使用 ${prefix}字段名，例如 ${prefix}releaseSubject。`;if(bindings[state.block].some((x,i)=>i!==index&&x.target===b.target))return '目标字段已经有绑定，不能重复配置。';const [o,p]=b.ontology.split('.');if(!obj(o)?.props.some(x=>x.id===p))return '请选择一个有效的业务属性。';if(state.block==='mapping'&&b.target==='mapping[].releaseItemId'&&b.ontology!=='Mapping.releaseItemRef')return '整机发布项引用需要绑定 Mapping.releaseItemRef，不能使用物料编码。';if(state.block==='mapping'&&b.target==='mapping[].moduleOrderId'&&b.ontology!=='Mapping.moduleOrderRef')return '模块子单引用需要绑定 Mapping.moduleOrderRef。';return ''}
function runValidation(){state.checked=true;state.checkedAt=now();state.drawer.confirm=false;const results=validationResults();const failed=results.some(r=>r.status==='阻断'),unknown=results.some(r=>r.status==='未知');log('规则校验','REL-2026-0108 · 发布预校验',unknown?'未能取得数据':failed?'阻断':'通过',results.map(r=>`${r.rule.id} ${r.rule.name}：${r.status}`).join('；'));state.logs[0].evidence={releaseOrderId:'REL-2026-0108',documentVersion:3,results:results.map(r=>({ruleId:r.rule.id,version:r.rule.version,status:r.status,source:r.rule.source,evidence:r.proof}))};drawOverlay();render()}
const actionsMap={
route:el=>navigate(el.dataset.route),
menu:()=>{state.mobile=!state.mobile;render()},
guide:()=>openDrawer('guide',{}, {readonly:true}),changes:()=>openDrawer('changes',{}, {readonly:true}),
'guide-route':el=>navigate(el.dataset.route),
close:()=>closeOverlay(),
'keep-editing':()=>drawOverlay(),
'discard-edit':()=>closeOverlay(true),
'select-object':el=>{state.object=el.dataset.id;state.tab='props';render()},
'object-tab':el=>{state.tab=el.dataset.tab;render()},
'preview-tab':()=>{closeOverlay(true);state.tab='preview';render()},
'add-object':()=>openWizard(),
'add-prop':()=>openDrawer('prop',{name:'',id:'',type:'文本',source:'PIS 数据库',path:'',value:'示例值',sample:'示例值'},{index:-1}),
'edit-prop':el=>{const i=Number(el.dataset.index);openDrawer('prop',obj().props[i],{index:i})},
'object-strategy':()=>openDrawer('strategy',obj().strategy||{stable:'每 30 分钟同步',dynamic:'提交时重新查询',timeout:'返回未能取得数据',duplicate:'阻止发布配置并提示'}),
'save-strategy':()=>{obj().strategy={...state.drawer.draft};obj().status='有变更';changed();log('配置编辑',`${obj().name} · 数据更新方式`);closeOverlay(true);render();toast('数据更新方式已保存到工作区草稿')},
 'test-prop':()=>{const d=state.drawer,p=d.draft;const err=validProp(p,d.index);if(err)return errorDrawer(err);let sample=transformedValue(p);if((sample===null||sample==='')&&!p.required&&!p.key){d.error='';d.tested=true;d.output=sample;drawOverlay();return}if(!validSample(sample,p.type)){d.tested=false;d.testError=`源值不能转换为${p.type}。请修改示例值或类型。`;drawOverlay();return}d.error='';d.testError='';d.tested=true;d.output=sample;log('对应关系测试',`${obj().name}.${p.id}`,'通过',`${p.source} / ${p.path} → ${p.id}`);drawOverlay()},
'save-prop':()=>{const d=state.drawer,p=d.draft;const err=validProp(p,d.index);if(err)return errorDrawer(err);if(!d.tested)return errorDrawer('请先测试此对应关系，测试通过后再保存。');if(p.key)obj().props.forEach(x=>x.key=false);if(p.display)obj().props.forEach(x=>x.display=false);p.value=d.output;if(d.index===-1)obj().props.push({...p});else obj().props[d.index]={...p};obj().status='有变更';changed();closeOverlay(true);render();toast('属性及数据来源已保存到草稿')},
 'test-object':()=>{const error=configErrors().find(e=>e.includes(obj().name));if(error)return toast(error);log('对应关系测试',`${obj().name} · 全部属性`,'通过','基于当前配置及单条示例值检查');openDrawer('testObject',{}, {readonly:true})},
'add-relation':()=>openDrawer('relation',{name:'',from:'ReleaseOrder',to:'ReleaseItem',card:'一对多（1:N）',method:'字段关联',left:'releaseOrderId',right:'mainOrderId'},{index:-1}),
'edit-relation':el=>{const i=Number(el.dataset.index);openDrawer('relation',relations[i],{index:i})},
'test-relation':()=>{const d=state.drawer,r=d.draft;if(!r.name.trim()||!r.left||!r.right)return errorDrawer('请填写关系名称并选择两端关联属性。');if(r.from==='Mapping'&&r.to==='ReleaseItem'&&(r.left!=='releaseItemRef'||r.right!=='releaseItemId'))return errorDrawer('Mapping 必须通过发布项行 ID 关联，不能仅按物料编码匹配。');if(r.method==='中间表'&&(!r.joinTable?.trim()||!r.joinOn?.trim()))return errorDrawer('请填写关联表及关联条件。');const a=obj(r.from)?.props.find(p=>p.id===r.left),b=obj(r.to)?.props.find(p=>p.id===r.right);if(r.method==='字段关联'&&String(a?.value)!==String(b?.value))return errorDrawer('样例未命中：两个属性值不相等，请检查关联字段。');d.error='';d.tested=true;drawOverlay();log('关系测试',r.name,'通过',`${r.from}.${r.left} → ${r.to}.${r.right}`)},
'save-relation':()=>{const d=state.drawer;if(!d.tested)return errorDrawer('请先测试关联，确认字段与业务业务含义一致。');if(d.index===-1)relations.push({...d.draft});else relations[d.index]={...d.draft};changed();closeOverlay(true);render();toast('业务关系已保存到草稿')},
'binding-block':el=>{state.block=el.dataset.block;render()},
'add-binding':()=>openDrawer('binding',{label:'',target:{main:'mainOrder.',items:'releaseItems[].',modules:'moduleOrders[].',mapping:'mapping[].'}[state.block],ontology:'ReleaseOrder.releaseSubject',method:'用户表达 / 智能建议',direction:'建议写入',policy:'保留用户修改'},{index:-1}),
'edit-binding':el=>{const i=Number(el.dataset.index);openDrawer('binding',bindings[state.block][i],{index:i})},
 'test-one-binding':()=>{const d=state.drawer,err=validBinding(d.draft,d.index);if(err)return errorDrawer(err);d.error='';d.tested=true;drawOverlay()},
'save-binding':()=>{const d=state.drawer,err=validBinding(d.draft,d.index);if(err)return errorDrawer(err);if(!d.tested)return errorDrawer('请先测试绑定，检查目标路径和输出值。');if(d.index===-1)bindings[state.block].push({...d.draft});else bindings[state.block][d.index]={...d.draft};changed();state.checked=false;state.submitted=false;log('配置编辑',`${blockNames[state.block]} · ${d.draft.label}`);closeOverlay(true);render();toast('字段绑定已保存到草稿')},
 'test-binding':()=>{openDrawer('action',{}, {index:1,readonly:true});log('绑定测试','产品发布单 V3 · 请求结构预览','通过','根据当前四个区块的绑定配置生成示例请求体')},
'action-detail':el=>openDrawer('action',{}, {index:Number(el.dataset.index),readonly:true}),
'smart-draft':()=>openDrawer('smart',{request:'给项目 PRJ-2026-A 创建欧洲发布单，整机 MAT-20260081，软件 SW-20260032，发布主题为“欧洲版主程序升级”。',subject:state.subject},{subjectEdited:!!state.subjectEdited}),
'generate-smart':()=>{const d=state.drawer,t=d.draft.request||'';if(!['PRJ-2026-A','MAT-20260081','SW-20260032'].every(code=>t.includes(code)))return errorDrawer('当前原型只支持示例项目 PRJ-2026-A、整机 MAT-20260081 和软件 SW-20260032，请在需求中包含这些编码。');d.generated=true;const match=t.match(/发布主题(?:为|是|：|:)?[“"「]?([^”"」。]+)[”"」]?/);d.suggestedSubject=match?.[1]?.trim()||state.subject;if(!d.subjectEdited)d.draft.subject=d.suggestedSubject;d.dirty=true;d.error='';drawOverlay();log('智能建议','按字段绑定生成建议','成功','使用内置样例解析，不调用大模型')},
'save-smart':()=>{const d=state.drawer;if(!d.draft.subject?.trim())return errorDrawer('发布主题不能为空。');state.subject=d.draft.subject.trim();state.subjectEdited=!!d.subjectEdited;state.formSaved=true;state.checked=false;state.submitted=false;log('业务动作','模拟保存发布草稿','成功','发布主题及四个区块均已保存；用户修改被保留');state.logs[0].evidence=buildPayload();closeOverlay(true);toast('模拟草稿已保存，可以执行预校验');openDrawer('validate',{})},
'save-form':()=>{state.formSaved=true;log('业务动作','模拟保存发布草稿','成功','调用示例业务动作，未发送真实请求');toast('模拟草稿已保存');openDrawer('validate',{})},
'edit-rule':el=>{const i=Number(el.dataset.index);openDrawer('rule',{...rules[i],sampleCase:'业务不满足'},{index:i,readonly:i===4})},
'test-rule':()=>{const d=state.drawer;if(!d.draft.name.trim()||!d.draft.condition.trim()||!d.draft.fact.trim()||!d.draft.judge.trim())return errorDrawer('请填写规则名称、适用条件、所需事实和判断要求。');d.tested=true;d.error='';log('规则测试',d.draft.name,d.draft.sampleCase==='满足条件'?'通过':d.draft.sampleCase==='接口超时'?'未能取得数据':d.draft.level,'执行内置样例模板');drawOverlay()},
'save-rule':()=>{const d=state.drawer;if(!d.tested)return errorDrawer('请先运行模板样例测试。');rules[d.index]={...d.draft};changed();state.checked=false;state.submitted=false;closeOverlay(true);render();toast('规则配置已保存，旧校验结果已失效')},
validate:()=>openDrawer('validate',{}),
'run-validation':()=>runValidation(),
repair:()=>{state.repaired=true;state.checked=false;state.submitted=false;state.drawer.confirm=false;log('数据修复','模拟补齐产品图片','成功','PIS 示例 hasImage 从 false 改为 true；原预校验失效');drawOverlay();render();toast('模拟图片已补齐，请重新预校验')},
'retry-plm':()=>{state.timeout=false;runValidation()},
'locate-issue':el=>{state.drawer.issue=Number(el.dataset.index);drawOverlay();overlayRoot.querySelector(`#result-${el.dataset.index}`)?.scrollIntoView({block:'nearest',behavior:'smooth'})},
submit:()=>{if(!canSubmit())return toast('请处理阻断或未知项，并重新预校验');state.drawer.confirm=true;drawOverlay();overlayRoot.querySelector('.drawer-body').scrollTo({top:99999,behavior:'smooth'})},
'confirm-submit':()=>{if(!canSubmit()){state.drawer.confirm=false;drawOverlay();return toast('必要事实已变化，请重新校验')}const results=validationResults();state.submitted=true;state.drawer.confirm=false;log('最终校验','REL-2026-0108 · 后端终检（模拟）','通过','重新取得必要事实并执行启用规则');state.logs[0].evidence={results:results.map(x=>({id:x.rule.id,version:x.rule.version,result:x.status,source:x.proof}))};log('业务提交','REL-2026-0108 · 模拟提交','成功','单据版本 3；包含 RI-001、MO-001、MP-001；未调用真实接口');state.logs[0].evidence={documentVersion:3,...buildPayload()};drawOverlay();render();toast('模拟提交完成，执行记录已生成')},
'check-release':()=>openDrawer('checkRelease',{}, {readonly:true}),
publish:()=>{const errors=configErrors();if(errors.length){openDrawer('checkRelease',{}, {readonly:true});return}if(state.released)return toast('当前配置已经发布');if(state.dirty)state.version++;state.released=true;state.dirty=false;objects.forEach(o=>{o.status='已发布';if(o.version==='草稿')o.version='v1.0'});log('配置发布',`release-app-v${state.version}.0`,'成功','模型、对应关系、关系、绑定、启用规则作为关联版本发布（模拟）');closeOverlay(true);state.route='release';render();toast('模拟配置包已发布')},
'log-detail':el=>openDrawer('log',{}, {index:Number(el.dataset.index),readonly:true}),
'export-logs':()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify({prototype:true,scope:'current-session',logs:state.logs},null,2)],{type:'application/json'}));a.href=url;a.download='业务对象平台-模拟会话记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前会话的模拟记录')},
'graph-node':el=>{state.object=el.dataset.id;navigate('objects')},
'graph-instance':()=>openDrawer('instance',{}, {object:'ReleaseOrder',readonly:true}),
 'test-connections':()=>{log('连接测试','共享连接可用性（模拟）','成功','5 个示例连接均返回内置测试数据');toast('示例连接测试通过，未发送网络请求')},
 'ask-preset':el=>askQuestion(el.dataset.text),ask:()=>askQuestion(document.getElementById('chat-question')?.value||''),
 'wizard-mode':el=>{const w=state.wizard;w.mode=el.dataset.mode;w.tableIndex=-1;w.tableQuery='';w.error='';if(w.mode==='manual')w.objectAction='new';w.stable=w.mode==='api'?'按需实时查询':w.mode==='manual'?'用户输入':'每 30 分钟同步';initWizardFields();drawOverlay()},
 'wizard-object-action':el=>{const w=state.wizard;w.objectAction=el.dataset.mode;w.error='';initWizardFields();drawOverlay()},
 'wizard-table':el=>{state.wizard.tableIndex=Number(el.dataset.index);initWizardFields();state.wizard.dirty=true;drawOverlay();overlayRoot.querySelector('.wizard-source-preview')?.scrollIntoView({block:'nearest'})},
 'new-connection':()=>{const w=state.wizard;w.newConnection=!w.newConnection;w.connectionTested=false;w.connection='IRDMS';w.tableIndex=-1;w.tableQuery='';initWizardFields();drawOverlay()},
 'wizard-test-connection':()=>{const w=state.wizard;if(w.connectionFailure){w.connectionTested=false;return errorWizard('模拟连接失败：无法连接数据库。请检查地址及服务名，或取消“模拟连接失败”后重试。')}if(!String(w.connName??'研发数据连接').trim())return errorWizard('请填写连接名称。');if(!String(w.host??'demo-db.internal').trim()||!String(w.database??'IRDMS_DEMO').trim())return errorWizard('请填写主机地址和数据库 / 服务名。');w.connectionTested=true;w.error='';drawOverlay();toast('模拟连接成功，已加载示例表结构')},
 'wizard-prev':()=>{state.wizard.step--;state.wizard.error='';drawOverlay()},
 'wizard-next':()=>wizardNext(),
 'wizard-save':()=>saveWizard()
};
for(const [a,r]of Object.entries({'to-relations':'relations','to-release':'release','to-runs':'runs','to-chat':'chat'}))actionsMap[a]=()=>navigate(r);
function askQuestion(t){if(!t.trim())return toast('请输入一个问题');state.chat.push({user:true,text:t});let answer;if(/Mapping|对应关系|关联/i.test(t))answer='Mapping 应引用当前主单内的具体发布行：<b>releaseItemRef = RI-001</b>，模块子单为 <b>moduleOrderRef = MO-001</b>。<br>物料编码 MAT-20260081 用于展示；不同区域或配置下，同一物料可能出现在多个发布行。<div class="proof section-gap">依据：Mapping 对象关系定义 · v1.0</div>';else if(/发布|提交|缺|为什么/.test(t)){const rs=validationResults().filter(r=>r.status!=='通过');answer=rs.length?rs.map(r=>`<b>${r.rule.name}：${r.status}</b><br>${r.detail}<br><small class="muted">${esc(r.proof)} · ${r.rule.id} ${r.rule.version}</small>`).join('<hr class="divider">'):'当前示例事实满足全部启用规则。仍需用户确认提交，并由发布单后端终检。';answer+=`<div class="section-gap">${btn('打开发布校验','validate','sm','shield')}</div>`;}else answer='当前原型仅演示发布阻断原因与 Mapping 关系说明。可尝试问“为什么不能提交”或“Mapping 应该关联什么”。<br><span class="muted">未连接实时大模型，不生成其他业务结论。</span>';state.chat.push({html:answer});render()}
function wizardNext(){const w=state.wizard;w.error='';if(w.step===0&&w.mode==='db'){if(w.newConnection&&!w.connectionTested)return errorWizard('请先测试新增数据库连接。');if(!wizardSchema())return errorWizard('请先选择来源表，查看字段结构与样例后继续。');}if(w.step===1){if(w.objectAction==='existing'){if(!objects.some(o=>o.id===w.existingObject))return errorWizard('请选择要对应关系到的已有业务对象。');}else{if(!w.objectName.trim()||!/^[A-Za-z][A-Za-z0-9_]*$/.test(w.objectId))return errorWizard('请按业务含义填写业务对象名称及合法标识（英文字母开头，字母、数字或下划线）。');if(objects.some(o=>o.id===w.objectId))return errorWizard('该对象英文代号已存在，可切换“给已有对象添加数据来源”补充来源。');if(!w.fields.some(f=>f.include&&f.id===w.key))return errorWizard('唯一编号必须是已选择的业务属性。');if(!w.fields.some(f=>f.include&&f.id===w.display))return errorWizard('列表显示名称必须选择一个已纳入的属性。');w.fields.forEach(f=>f.key=f.id===w.key);}if(!w.fields.some(f=>f.include))return errorWizard('请至少选择一个参与对应关系的来源字段。');}if(w.step===2){const selected=w.fields.filter(f=>f.include);if(w.objectAction==='existing'){const target=objects.find(o=>o.id===w.existingObject);if(!target)return errorWizard('目标对象已不存在，请重新选择。');if(selected.some(f=>!target.props.some(p=>p.id===f.target)))return errorWizard('请为每个来源字段选择对应的业务属性。');if(new Set(selected.map(f=>f.target)).size!==selected.length)return errorWizard('多个来源字段不能重复对应关系到同一属性。');if(!selected.some(f=>target.props.some(p=>p.id===f.target&&p.key)))return errorWizard('必须对应关系目标对象的唯一编号，以识别同一业务记录。');if(selected.some(f=>target.props.find(p=>p.id===f.target).type!==f.type))return errorWizard('来源字段与目标属性类型不一致，请调整字段选择或对应关系。');}else{if(selected.some(f=>!f.name.trim()||!/^[A-Za-z][A-Za-z0-9_]*$/.test(f.id)))return errorWizard('请为每个属性填写中文名和合法的英文标识。');if(new Set(selected.map(f=>f.id)).size!==selected.length)return errorWizard('存在重复的属性英文代号，请修改后继续。');}}w.step++;drawOverlay();}
function saveWizard(){const w=state.wizard;if(w.simulateDuplicate)return errorWizard('示例中存在重复主键，无法保存；请取消模拟重复或修复源数据。');if(w.fields.some(f=>f.include&&!validSample(f.sample,f.type)))return errorWizard('有属性的源值与目标类型不匹配，请返回设置字段对应关系调整。');if(w.objectAction==='existing'){const target=objects.find(o=>o.id===w.existingObject);if(!target)return errorWizard('目标对象已不存在，请重新选择。');changed();state.object=target.id;state.domain='ALL';state.query='';state.tab='abilities';state.route='objects';log('数据来源',target.name,'成功',`${wizardSchema().table} → ${target.id}；新增独立数据查询`);closeOverlay(true);render();return}if(objects.some(o=>o.id===w.objectId))return errorWizard('对象已存在，请避免重复创建。');const schema=wizardSchema();const source=w.mode==='manual'?'用户输入':w.mode==='api'?wizardApiAbility().name:w.connection==='PIS'?'PIS 数据库':w.newConnection?`${w.connName||'研发数据连接'} 数据库`:'IRDMS 数据库';const created={id:w.objectId,name:w.objectName,count:1,domain:w.domain,version:'草稿',status:'草稿',desc:`${w.mode==='manual'?'手工定义':`从 ${schema.table} 接入`}的业务对象，待检查后发布。`,strategy:{stable:w.stable,dynamic:'提交时重新查询',timeout:'返回未能取得数据',duplicate:'阻止发布配置并提示'},props:w.fields.filter(f=>f.include).map(f=>prop(f.name,f.id,f.type,source,w.mode==='manual'?`input.${f.id}`:w.mode==='api'?f.column:`${schema.table}.${f.column}`,convertWizardValue(f),{key:f.key,display:f.id===w.display,required:f.key}))};objects.push(created);if(w.mode==='db'&&w.newConnection)connections.push([w.connName||'研发数据连接',`${w.connType||'Oracle'} · ${w.database||'IRDMS_DEMO'}`,'数据库',w.objectName,w.stable]);changed();state.object=created.id;state.domain='ALL';state.query='';state.tab='props';state.route='objects';log('对象创建',created.name,'成功',`${schema.table} → ${created.id}；保存为草稿，未同步生产数据`);closeOverlay(true);render();toast(`已创建“${created.name}”草稿，可继续配置关系与应用绑定`)}

// 事件委托同时服务主页面和抽屉。
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){const fn=actionsMap[el.dataset.action];if(fn)fn(el);else console.warn('未绑定交互',el.dataset.action)}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.input==='object-search'){state.query=el.value;document.getElementById('object-items').innerHTML=objectItems();return}if(el.dataset.field&&state.drawer){const key=el.dataset.field;state.drawer.draft[key]=el.value;state.drawer.dirty=true;state.drawer.tested=false;state.drawer.error='';if(key==='request')state.drawer.generated=false;if(key==='subject')state.drawer.subjectEdited=true;return}if(el.dataset.wfield&&state.wizard){const w=state.wizard,key=el.dataset.wfield;w[key]=el.value;w.dirty=true;if(['host','database','port','user','password','connType','schema'].includes(key))w.connectionTested=false;if(key==='tableQuery')document.getElementById('wizard-tables').innerHTML=wizardTableList();return}if(el.dataset.wmap&&state.wizard){const f=state.wizard.fields[Number(el.dataset.wmap)],key=el.dataset.mapkey,old=f.id;f[key]=el.value;if(key==='id'){if(state.wizard.display===old)state.wizard.display=f.id;if(f.key)state.wizard.key=f.id}state.wizard.dirty=true;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='domain'){state.domain=el.value;render();return}if(el.dataset.change==='binding-scene'){state.bindingScene=el.value;toast(el.value==='产品范围发布'?'产品范围发布：先核对物料可选范围，再使用相同字段绑定':'已切换为普通产品发布');return}if(el.hasAttribute('data-validate-timeout')){state.timeout=el.checked;state.checked=false;state.submitted=false;state.drawer.confirm=false;drawOverlay();render();return}if(el.dataset.check&&state.drawer){state.drawer.draft[el.dataset.check]=el.checked;state.drawer.dirty=true;state.drawer.tested=false;return}if(el.dataset.field&&state.drawer){const d=state.drawer,k=el.dataset.field;d.draft[k]=el.value;d.tested=false;d.dirty=true;if(d.type==='relation'&&['from','to'].includes(k)){d.draft[k==='from'?'left':'right']=obj(el.value)?.props[0]?.id||''}if(['source','from','to','method','ontology'].includes(k))drawOverlay();return}if(el.dataset.wfield&&state.wizard){const w=state.wizard,k=el.dataset.wfield;if(k==='connection'){w.connection=el.value;w.tableIndex=-1;w.tableQuery='';initWizardFields();drawOverlay()}else if(k==='existingObject'){w.existingObject=el.value;selectWizardObject();drawOverlay()}else if(k==='key'){w.key=el.value;w.fields.find(f=>f.id===w.key).include=true;w.fields.forEach(f=>f.key=f.id===w.key);drawOverlay()}return}if(el.hasAttribute('data-winclude')){const w=state.wizard;w.fields[Number(el.dataset.winclude)].include=el.checked;w.dirty=true;return}if(el.dataset.wcheck&&state.wizard){const w=state.wizard;w[el.dataset.wcheck]=el.checked;if(el.dataset.wcheck==='connectionFailure')w.connectionTested=false;drawOverlay();return}if(el.dataset.wmap&&state.wizard){state.wizard.fields[Number(el.dataset.wmap)][el.dataset.mapkey]=el.value;state.wizard.dirty=true;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(state.drawer||state.wizard)){e.preventDefault();closeOverlay();return}if(e.key==='Enter'&&e.target.id==='chat-question'){e.preventDefault();askQuestion(e.target.value);return}if(e.key==='Tab'&&(state.drawer||state.wizard)){const focusables=[...overlayRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href]')].filter(x=>x.getClientRects().length);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const initialRoute=location.hash.slice(1);if(pages[initialRoute])state.route=initialRoute;render();

function sourceSummary(o){const sources=[...new Set(o.props.map(p=>p.source))];return `<div class="source-strip">${sources.slice(0,3).map((source,i)=>`<div class="source-mini"><div class="system-icon ${source.includes('接口')?'api':''}">${source.includes('数据库')?'DB':source.includes('接口')?'API':'VAL'}</div><div><b>${esc(source)}</b><small>${esc(source.includes('数据库')?(o.strategy?.stable||'每 30 分钟同步'):source.includes('接口')?(o.strategy?.dynamic||'按需实时查询'):'运行时获取')}</small></div></div>${i<Math.min(sources.length,3)-1?'<span class="strip-line"></span>':''}`).join('')}<button class="link" style="margin-left:auto;font-size:11px;display:flex;align-items:center" data-action="object-strategy">数据更新方式 ${icon('chevron')}</button></div>`}
function transformedValue(p){let v=p.sample??p.value;if(v===null||v===undefined||String(v).trim()===''){if(p.nullPolicy==='保留已有值')return p.value;return null}if(p.conversion==='去除首尾空格')v=String(v).trim();if(p.conversion==='转换为文本')v=String(v);if(p.conversion==='枚举：Y/N → 是/否')v=v==='Y'?'是':v==='N'?'否':v;if(p.type==='数字'&&validSample(v,p.type))v=Number(v);if(p.type==='布尔'&&validSample(v,p.type))v=['true','Y','是'].includes(String(v));return v}
function referenceView(o){const list=[];for(const [block,bs]of Object.entries(bindings)){const matches=bs.filter(b=>b.ontology.startsWith(o.id+'.'));if(matches.length)list.push([`产品发布单 / ${blockNames[block]}`,matches.map(b=>b.label).join('、'),'bindings'])}const rr=rules.filter(r=>r.obj===o.name);if(rr.length)list.push(['发布校验规则',rr.map(r=>r.name).join('、'),'rules']);if(!list.length)return `<div class="empty">${icon('bind')}<b>尚无应用直接引用此对象</b>为对象配置字段绑定或规则后，可在此查看依赖。<div class="section-gap">${btn('添加应用字段绑定','route','','bind','data-route="bindings"')}</div></div>`;return `<div class="panel-body">${list.map(([t,d,r])=>`<div class="release-line"><div class="release-check">${icon('check')}</div><div class="fill"><h4>${esc(t)}</h4><p>${esc(d)}</p></div><button class="link" data-action="route" data-route="${r}">查看引用</button></div>`).join('')}<div class="section-gap">${inf('被发布中配置引用的属性不能直接删除或重命名其标识。','amber')}</div></div>`}
